// android/ is regenerated by `expo prebuild`, so the release signing config has to be added here rather than edited
// into build.gradle by hand. The key comes from environment variables (GitHub secrets in the release workflow); when
// they are not set, release builds keep the template's debug key so local builds still work.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_SIGNING = `
        release {
            if (System.getenv('ANDROID_KEYSTORE_PATH')) {
                storeFile file(System.getenv('ANDROID_KEYSTORE_PATH'))
                storePassword System.getenv('ANDROID_KEYSTORE_PASSWORD')
                keyAlias System.getenv('ANDROID_KEY_ALIAS')
                keyPassword System.getenv('ANDROID_KEY_PASSWORD')
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents;
    if (gradle.includes("System.getenv('ANDROID_KEYSTORE_PATH')")) return config;

    const debugSigning = /(signingConfigs \{\s*debug \{[^}]*\})/;
    const releaseUsesDebug = /(release \{[^}]*?)signingConfig signingConfigs\.debug/;
    if (!debugSigning.test(gradle) || !releaseUsesDebug.test(gradle)) {
      throw new Error('withReleaseSigning: build.gradle no longer matches the expected template; update the plugin.');
    }

    gradle = gradle.replace(debugSigning, `$1${RELEASE_SIGNING}`);
    gradle = gradle.replace(
      releaseUsesDebug,
      "$1signingConfig System.getenv('ANDROID_KEYSTORE_PATH') ? signingConfigs.release : signingConfigs.debug",
    );
    config.modResults.contents = gradle;
    return config;
  });
};
